#!/bin/bash
# JobTracker Seed Data Import Script
set -e

echo "=== Importing Seed Data ==="

# 等待 PostgreSQL 就绪
echo "Waiting for PostgreSQL to be ready..."
for i in {1..30}; do
    PG_POD=$(kubectl get pod -l component=database -o jsonpath="{.items[0].metadata.name}" 2>/dev/null)
    if [ -n "$PG_POD" ]; then
        STATUS=$(kubectl get pod $PG_POD -o jsonpath="{.status.phase}" 2>/dev/null)
        if [ "$STATUS" = "Running" ]; then
            echo "PostgreSQL pod is running: $PG_POD"
            break
        fi
    fi
    echo "Waiting... ($i/30)"
    sleep 10
done

if [ -z "$PG_POD" ]; then
    echo "ERROR: PostgreSQL pod not found"
    exit 1
fi

if [ "$STATUS" != "Running" ]; then
    echo "ERROR: PostgreSQL pod is not Running (status=$STATUS)"
    kubectl describe pod "$PG_POD" | tail -50
    exit 1
fi

# 确保 jobtracker 数据库和表结构存在
DB_EXISTS=$(kubectl exec $PG_POD -- psql -U postgres -tAc "SELECT 1 FROM pg_database WHERE datname='jobtracker'" 2>/dev/null | tr -d ' ')
if [ "$DB_EXISTS" != "1" ]; then
    echo "Creating jobtracker database..."
    kubectl exec $PG_POD -- psql -U postgres -c "CREATE DATABASE jobtracker;"
fi

TABLE_EXISTS=$(kubectl exec $PG_POD -- psql -U postgres -d jobtracker -tAc "SELECT to_regclass('public.companies')" 2>/dev/null | tr -d ' ')
if [ -z "$TABLE_EXISTS" ] || [ "$TABLE_EXISTS" = "NULL" ]; then
    echo "Applying database schema..."
    cat backend/migrations/init.sql | kubectl exec -i $PG_POD -- psql -U postgres -d jobtracker
fi

# 检查是否已有数据
echo "Checking existing data..."
COUNT=$(kubectl exec $PG_POD -- psql -U postgres -d jobtracker -t -c "SELECT COUNT(*) FROM companies;" 2>/dev/null | tr -d ' ' || echo "0")

echo "Setting up SME data..."
if [ -f data/sme_companies.json ]; then
    kubectl create configmap sme-data --from-file=data/sme_companies.json --dry-run=client -o yaml | kubectl apply --server-side --force-conflicts -f - || echo "Warning: failed to update sme-data ConfigMap"
    kubectl rollout restart deployment/jobtracker-backend || true
    echo "SME data setup complete"
else
    echo "Warning: data/sme_companies.json not found, skipping SME ConfigMap"
fi

if [ "$COUNT" -gt 0 ] && [ "$1" != "--restore" ] && [ "${RESTORE:-0}" != "1" ]; then
    echo "Database already has $COUNT companies, skipping seed. Use --restore to replace."
    exit 0
fi

if [ "$1" = "--restore" ] || [ "${RESTORE:-0}" = "1" ]; then
    echo "Restore mode: clearing companies table..."
    kubectl exec "$PG_POD" -- psql -U postgres -d jobtracker -c "TRUNCATE companies RESTART IDENTITY CASCADE;"
fi

# 导入完整公司备份
echo "Importing companies backup..."
kubectl exec -i $PG_POD -- psql -U postgres -d jobtracker << 'EOF'
insert into public.companies (id, name, name_en, logo_url, website, industry, "group", description, is_preset, health_status, last_checked, created_at, updated_at, deleted_at) values ('d8cc5b81-3c76-4180-973a-f697a072cf75', '阿里云', 'Alibaba Cloud', NULL, 'https://careers.aliyun.com', '云计算', 'cloud', '全球领先的云计算及人工智能科技公司', true, 'GREEN', '2026-07-22 15:38:26.535869 +00:00', '2026-07-18 08:48:47.017386 +00:00', '2026-07-22 15:38:27.873101 +00:00', null);
